function saveProactiveIdle(id){const c=getC(id),el=$('#pa_idle');if(!c||!el)return;const before=Math.max(0,Number(c.proactive.idleMin)||0);c.proactive.idleMin=Math.max(0,Math.min(1440,parseInt(el.value,10)||0));if(c.proactive.enabled&&before!==c.proactive.idleMin)initiativeArm(c);save();render();if(c.proactive.serverPush)roleServerPushSync(c,true);toast('已保存：只调整「'+(c.remark||c.name)+'」的主动联系间隔');}

/* ---------- 多选转发 ---------- */
let _sel=null,_gmsel=null,_gfwd=null;
function enterSelect(id,mode){_sel={id,ids:[],mode:mode==='delete'?'delete':'forward'};const p=$('#panel');if(p)p.classList.remove('show');render();}
function exitSelect(){_sel=null;render();}
async function delSelected(id){if(!_sel||!_sel.ids.length){toast('先选几条');return;}if(!await uiConfirm('删除选中的 '+_sel.ids.length+' 条消息？'))return;S.messages[mkey(id)]=msgs(id).filter(m=>_sel.ids.indexOf(m.id)<0);_sel=null;await persistWechatMessagesNow();render();toast('已删除');}
function toggleSel(mid){if(!_sel)return;const i=_sel.ids.indexOf(mid);const on=i<0;if(on)_sel.ids.push(mid);else _sel.ids.splice(i,1);
  const tk=$('#tk_'+mid);if(tk){tk.textContent=on?'☑':'⚪';tk.style.color=on?'#07c160':'#555';}
  const fc=$('#fwdcnt');if(fc)fc.textContent=_sel.ids.length;}
function forwardSelected(){if(!_sel||!_sel.ids.length){toast('先选几条');return;}
  const from=_sel.id;const accts=(S.me.accounts&&S.me.accounts.length)?S.me.accounts:[{id:'main',name:S.me.name}];
  let html='<h3>转发聊天记录给</h3><div class="hint">可以转给当前身份的好友，也能转到某个小号身份下的角色（切到那个小号就能看到）。</div>';
  accts.forEach(a=>{
    const list=S.contacts.filter(c=>!c.deleted&&c.id!==from&&(a.id==='main'||(c._added&&c._added[a.id])||S.messages[c.id+'#'+a.id]));
    html+=`<div style="font-weight:600;color:#ff8fab;padding:10px 4px 4px">${esc(a.name)}${a.id===actId()?'（当前）':a.id==='main'?'（大号）':'（小号）'}</div>`;
    html+=list.length?list.map(c=>`<div class="section"><div class="it" onclick="doForward('${c.id}','${a.id}')">${av(c.avatar,'sm')}<div class="meta" style="flex:1"><div class="n">${esc(c.remark||c.name)}</div></div><span class="v">›</span></div></div>`).join(''):'<div class="hint" style="padding:2px 8px;color:#777">这个身份还没加好友</div>';
  });
  html+='<button class="btn g" style="margin-top:10px" onclick="closeModal()">取消</button>';
  openModal(html);}
function doForward(toId,acctId){const from=_sel.id;const fromC=getC(from);const src=msgs(from);
  const picked=src.filter(m=>_sel.ids.includes(m.id)&&m.type!=='sys');
  const lines=picked.map(m=>({who:m.role==='user'?S.me.name:(fromC.name),text:previewOf(m)}));
  acctId=acctId||'main';const sameAcct=(acctId===actId());
  const key=(acctId==='main')?toId:toId+'#'+acctId;
  const card={role:'user',type:'chatlog',title:S.me.name+'和'+fromC.name+'的聊天记录',lines,time:Date.now(),id:uid()};
  S.messages[key]=S.messages[key]||[];S.messages[key].push(card);
  const tc=getC(toId);if(tc&&acctId!=='main'){tc._added=tc._added||{};tc._added[acctId]=true;}
  save();_sel=null;closeModal();
  if(sameAcct){toast('已转发聊天记录');scheduleReply(toId);openChat(toId);}
  else{const an=(accts2(acctId)||{}).name||acctId;toast('已转发到「'+an+'」身份的 '+(tc?(tc.remark||tc.name):'')+'，切到那个身份就能给ta看～');}}
function accts2(id){return (S.me.accounts||[]).find(a=>a.id===id);}
function openChatlog(mid){let m;for(const k in S.messages){m=S.messages[k].find(x=>x.id===mid);if(m)break;}if(!m)return;
  openModal(`<h3>${esc(m.title)}</h3><div style="max-height:60vh;overflow-y:auto">${(m.lines||[]).map(l=>`<div style="padding:6px 2px;border-bottom:.5px solid #2a2a2c;font-size:14px"><b style="color:#9ec5fe">${esc(l.who)}：</b>${esc(l.text)}</div>`).join('')}</div><button class="btn g" style="margin-top:10px" onclick="closeModal()">关闭</button>`);}

