function afterGroupComposer(c){const id=c.p==='pfgroup'?'pfg_input':c.p==='pfchat'?'pf_input':'ginput',ta=$('#'+id);if(!ta||ta._groupComposerBound)return;ta._groupComposerBound=1;ta.addEventListener('compositionend',function(){chatComposerReflow(this);chatComposerStateSync(this);});ta.addEventListener('input',function(){chatComposerReflow(this);chatComposerStateSync(this);});ta.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(c.p==='pfgroup')sendPhoneFriendGroup(c.gid);else if(c.p==='pfchat')sendPhoneFriend(c.id);else sendGroup(c.id);}});chatComposerStateSync(ta);}
